function createApp() {
  const routes = [];

  const app = (req, res) => {
    const url = new URL(req.url, 'http://localhost');
    const route = routes.find(
      (candidate) => candidate.method === req.method && candidate.path === url.pathname,
    );

    res.json = (payload) => {
